void swap(int* a, int* b) {
    int tmp = *a;     // läs värdet på adressen a
    *a = *b;
    *b = tmp;
}

int x = 1, y = 2;
swap(&x, &y);         // skicka adresserna
// nu är x == 2 och y == 1

void swap(int& a, int& b) {
    int tmp = a;
    a = b;
    b = tmp;
}

swap(x, y);           // anropet ser ut som vanligt

